import React, { useState, useEffect, useRef } from "react";
import "./App.css";

const API_FETCH_CUSTOMERS  = process.env.REACT_APP_API_URL_CUSTOMERS;
const API_FETCH_STORAGES   = process.env.REACT_APP_API_URL_STORAGES;
const API_FETCH_CATALOGS   = process.env.REACT_APP_API_URL_CATALOGS;
const API_ASSIGN_TRUCKS    = process.env.REACT_APP_API_ASSIGN_TRUCKS;

function App() {
  // --- Data from backend ---
  const [customers, setCustomers] = useState([]);
  const [storages, setStorages]   = useState([]);
  const [categories, setCatalogs] = useState([]);

  // --- Live‐search state for each customer block ---
  const [searchTerms, setSearchTerms]           = useState([]); // [ { customer: "" }, … ]
  const [customerSuggestions, setCustomerSuggestions] = useState([]); // [ [ … ], … ]

  // --- The array of "customer blocks" (each block has a chosen customer + productRows[]) ---
  const [customerBlocks, setCustomerBlocks] = useState([]);

  // --- A place to store the API response (assigned vehicles) ---
  const [assignedVehicles, setAssignedVehicles] = useState([]); 

  // For detecting clicks outside suggestion dropdowns
  const suggestionRefs = useRef([]);

  // ------------------------------------
  //  1) Fetch customers, storages, catalogs on mount
  // ------------------------------------
  useEffect(() => {
    fetch(API_FETCH_CUSTOMERS)
      .then(res => res.json())
      .then(data => {
        setCustomers(
          data.customers.map(c => ({
            id:       c.CustomerID,
            name:     c.CustomerName,
            address:  c.CustomerAddress,
            location: [c.CustomerLat, c.CustomerLong]
          }))
        );
      })
      .catch(console.error);

    fetch(API_FETCH_STORAGES)
      .then(res => res.json())
      .then(data => {
        setStorages(
          data.storages.map(s => ({
            id:       s.StorageID,
            name:     s.StorageName,
            address:  s.StorageAddress,
            location: [s.StorageLat, s.StorageLong]
          }))
        );
      })
      .catch(console.error);

    fetch(API_FETCH_CATALOGS)
      .then(res => res.json())
      .then(data => {
        setCatalogs(
          data.catalogs.map(c => ({
            id:   c.CatalogID,
            name: c.CatalogName
          }))
        );
      })
      .catch(console.error);
  }, []);

  // ------------------------------------
  //  2) Initialize with one empty customer block
  // ------------------------------------
  useEffect(() => {
    if (customerBlocks.length === 0) {
      addCustomerBlock();
    }
  }, []);

  // ------------------------------------
  //  3) Add / Remove Customer Blocks
  // ------------------------------------
  const addCustomerBlock = () => {
    const newBlock = {
      id:           Date.now() + Math.random(),
      CustomerID:   "",
      customerName: "",
      productRows: [
        {
          id:         Date.now() + Math.random() + 1,
          category:   "",
          quantity:   "",
          weight:     "",
          StorageID:  "",
          storageName:""
        }
      ]
    };
    setCustomerBlocks(prev => [...prev, newBlock]);
    setSearchTerms(prev => [...prev, { customer: "" }]);
    setCustomerSuggestions(prev => [...prev, []]);
  };

  const removeCustomerBlock = (blockIdx) => {
    setCustomerBlocks(prev => prev.filter((_, i) => i !== blockIdx));
    setSearchTerms(prev => prev.filter((_, i) => i !== blockIdx));
    setCustomerSuggestions(prev => prev.filter((_, i) => i !== blockIdx));
  };

  // ------------------------------------
  //  4) Update a field in a customer block
  // ------------------------------------
  const updateCustomerField = (blockIdx, field, value) => {
    setCustomerBlocks(prev =>
      prev.map((block, i) =>
        i === blockIdx ? { ...block, [field]: value } : block
      )
    );
  };

  // ------------------------------------
  //  5) Live search for a customer in block #blockIdx
  // ------------------------------------
  const handleCustomerSearch = (blockIdx, value) => {
    // 1) Update the search term
    setSearchTerms(prev =>
      prev.map((term, i) =>
        i === blockIdx ? { ...term, customer: value } : term
      )
    );

    // 2) Build suggestion list
    const suggestions = value.trim()
      ? customers
          .filter(c =>
            c.name.toLowerCase().includes(value.toLowerCase()) &&
            !customerBlocks.some((blk, bi) => bi !== blockIdx && blk.CustomerID === c.id)
          )
          .slice(0, 5)
      : [];

    setCustomerSuggestions(prev =>
      prev.map((arr, i) =>
        i === blockIdx ? suggestions : arr
      )
    );

    // 3) If user cleared input, clear the selection
    if (value === "") {
      updateCustomerField(blockIdx, "customerName", "");
      updateCustomerField(blockIdx, "CustomerID", "");
    } else {
      updateCustomerField(blockIdx, "customerName", value);
      updateCustomerField(blockIdx, "CustomerID", "");
    }
  };

  // ------------------------------------
  //  6) When user picks a suggestion
  // ------------------------------------
  const selectCustomer = (blockIdx, customer) => {
    updateCustomerField(blockIdx, "CustomerID",   customer.id);
    updateCustomerField(blockIdx, "customerName", customer.name);

    setCustomerSuggestions(prev =>
      prev.map((arr, i) => (i === blockIdx ? [] : arr))
    );
    setSearchTerms(prev =>
      prev.map((term, i) =>
        i === blockIdx ? { ...term, customer: undefined } : term
      )
    );
  };

  // ------------------------------------
  //  7) Close suggestion dropdown on outside click
  // ------------------------------------
  useEffect(() => {
    const onClickOutside = e => {
      suggestionRefs.current.forEach((ref, idx) => {
        if (ref && !ref.contains(e.target)) {
          setCustomerSuggestions(prev =>
            prev.map((arr, i) => (i === idx ? [] : arr))
          );
        }
      });
    };
    document.addEventListener("mousedown", onClickOutside);
    return () => document.removeEventListener("mousedown", onClickOutside);
  }, [suggestionRefs, customerSuggestions]);

  // ------------------------------------
  //  8) Product‐row handlers inside each block
  // ------------------------------------
  const addProductRow = (blockIdx) => {
    setCustomerBlocks(prev =>
      prev.map((block, i) => {
        if (i !== blockIdx) return block;
        return {
          ...block,
          productRows: [
            ...block.productRows,
            {
              id:         Date.now() + Math.random(),
              category:   "",
              quantity:   "",
              weight:     "",
              StorageID:  "",
              storageName:""
            }
          ]
        };
      })
    );
  };

  const removeProductRow = (blockIdx, prodIdx) => {
    setCustomerBlocks(prev =>
      prev.map((block, i) => {
        if (i !== blockIdx) return block;
        const newRows = block.productRows.filter((_, j) => j !== prodIdx);
        return {
          ...block,
          productRows: newRows.length > 0
            ? newRows
            : [
                {
                  id:         Date.now() + Math.random(),
                  category:   "",
                  quantity:   "",
                  weight:     "",
                  StorageID:  "",
                  storageName:""
                }
              ]
        };
      })
    );
  };

  const updateProductField = (blockIdx, prodIdx, field, value) => {
    setCustomerBlocks(prev =>
      prev.map((block, i) => {
        if (i !== blockIdx) return block;
        return {
          ...block,
          productRows: block.productRows.map((pr, j) =>
            j === prodIdx ? { ...pr, [field]: value } : pr
          )
        };
      })
    );
  };

  // ------------------------------------
  //  9) Submit: auto‐match, validate, flatten, POST
  // ------------------------------------
  const handleSubmit = async () => {
    // === Auto‐match any typed-but-not-clicked customerName → customerId ===
    for (let i = 0; i < customerBlocks.length; i++) {
      const blk = customerBlocks[i];
      if (!blk.CustomerID && blk.customerName.trim() !== "") {
        const match = customers.find(
          c => c.name.toLowerCase() === blk.customerName.trim().toLowerCase()
        );
        if (match) {
          blk.CustomerID = match.id;
        }
      }
    }

    // === Auto-match any typed-but-not-clicked storageName → storageId ===
    for (let i = 0; i < customerBlocks.length; i++) {
      const blk = customerBlocks[i];
      blk.productRows.forEach(pr => {
        if (!pr.StorageID && pr.storageName && pr.storageName.trim() !== "") {
          const match = storages.find(
            s => s.name.toLowerCase() === pr.storageName.trim().toLowerCase()
          );
          if (match) {
            pr.StorageID = match.id;
          }
        }
      });
    }

    // === Validation ===
    for (let i = 0; i < customerBlocks.length; i++) {
      const blk = customerBlocks[i];
      if (!blk.CustomerID) {
        alert(`Customer Block ${i + 1}: Please select a valid customer from the list.`);
        return;
      }
      for (let j = 0; j < blk.productRows.length; j++) {
        const pr = blk.productRows[j];
        if (!pr.category) {
          alert(`Block ${i + 1}, Product ${j + 1}: Select a category.`);
          return;
        }
        if (!pr.weight || isNaN(parseFloat(pr.weight))) {
          alert(`Block ${i + 1}, Product ${j + 1}: Enter a valid weight.`);
          return;
        }
        if (!pr.StorageID) {
          alert(`Block ${i + 1}, Product ${j + 1}: Please select a valid storage from the list.`);
          return;
        }
      }
    }

    // === Flatten into orders array ===
    const orders = [];
    customerBlocks.forEach(blk => {
      blk.productRows.forEach(pr => {
        const cat = categories.find(c => c.id === pr.category);
        const productName = cat ? cat.name : "";
        orders.push({
          CustomerID:  blk.CustomerID,
          productName,
          weight:      parseFloat(pr.weight),
          StorageID:   pr.StorageID,
          offRoute:    false
        });
      });
    });

    // === POST to /api/assign_trucks ===
    try {
      const response = await fetch(API_ASSIGN_TRUCKS, {
        method:  "POST",
        headers: { "Content-Type": "application/json" },
        body:    JSON.stringify({ orders })
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      console.log("Assigned Vehicles:", data.assigned_vehicles);
      setAssignedVehicles(data.assigned_vehicles);
    } catch (err) {
      console.error(err);
      alert("Error assigning trucks. See console for details.");
    }
  };

  // ------------------------------------
  //  10) Render JSX (form + results box)
  // ------------------------------------
  return (
    <div className="container">
      <header className="header">
        <div className="header-left">
          <h1 className="route-name">Assign Truck</h1>
        </div>
        <div className="header-right">
          <button className="btn add-customer-btn" onClick={addCustomerBlock}>
            + Add Customer
          </button>
        </div>
      </header>

      <div className="content">
        <main className="main-area">
          {customerBlocks.map((block, blockIdx) => (
            <div className="customer-block" key={block.id}>
              <div className="customer-header">
                {/* Customer live-search input */}
                <div
                  className="customer-cell"
                  ref={el => (suggestionRefs.current[blockIdx] = el)}
                >
                  <div className="suggestion-wrapper">
                    <input
                      className="input customer-input"
                      placeholder="Type to search customers…"
                      value={
                        searchTerms[blockIdx]?.customer !== undefined
                          ? searchTerms[blockIdx].customer
                          : block.customerName
                      }
                      onChange={e => handleCustomerSearch(blockIdx, e.target.value)}
                    />
                    {customerSuggestions[blockIdx]?.length > 0 && (
                      <ul className="suggestions-list">
                        {customerSuggestions[blockIdx].map(c => (
                          <li
                            key={c.id}
                            onClick={() => selectCustomer(blockIdx, c)}
                          >
                            {c.name} — {c.address}
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>
                </div>

                {/* Remove customer block (small red circle) */}
                <div className="remove-customer-cell">
                  <button
                    className="btn remove-customer-btn"
                    onClick={() => removeCustomerBlock(blockIdx)}
                  ></button>
                </div>
              </div>

              {/* Product rows */}
              {block.productRows.map((pr, prodIdx) => (
                <div className="product-row" key={pr.id}>
                  {/* Category dropdown */}
                  <div className="cell">
                    <select
                      className="input category-input"
                      value={pr.category}
                      onChange={e =>
                        updateProductField(blockIdx, prodIdx, "category", e.target.value)
                      }
                    >
                      <option value="">Select Category</option>
                      {categories.map(c => (
                        <option key={c.id} value={c.id}>
                          {c.name}
                        </option>
                      ))}
                    </select>
                  </div>

                  {/* Quantity input */}
                  <div className="cell">
                    <input
                      className="input quantity-input"
                      type="text"
                      placeholder="Quantity"
                      value={pr.quantity}
                      onChange={e =>
                        updateProductField(blockIdx, prodIdx, "quantity", e.target.value)
                      }
                    />
                  </div>

                  {/* Weight input */}
                  <div className="cell">
                    <input
                      className="input weight-input"
                      type="text"
                      placeholder="Weight"
                      value={pr.weight}
                      onChange={e =>
                        updateProductField(blockIdx, prodIdx, "weight", e.target.value)
                      }
                    />
                  </div>

                  {/* Storage dropdown */}
                  <div className="cell">
                    <select
                      className="input storage-input"
                      value={pr.StorageID}
                      onChange={e =>
                        updateProductField(blockIdx, prodIdx, "StorageID", e.target.value)
                      }
                    >
                      <option value="">Select Storage</option>
                      {storages.map(s => (
                        <option key={s.id} value={s.id}>
                          {s.name}
                        </option>
                      ))}
                    </select>
                  </div>

                  {/* Remove this product row (small red circle) */}
                  <div className="remove-product-cell">
                    <button
                      className="btn remove-product-btn"
                      onClick={() => removeProductRow(blockIdx, prodIdx)}
                    ></button>
                  </div>
                </div>
              ))}

              {/* "Add Product" button */}
              <button
                className="btn add-product-btn"
                onClick={() => addProductRow(blockIdx)}
              >
                + Add Product
              </button>
            </div>
          ))}

          {/* Submit button */}
          <div className="submit-btn-row">
            <button className="btn submit-btn" onClick={handleSubmit}>
              Submit
            </button>
          </div>

          {/* ════════════════════════════════════════════ */}
          {/*  11) Results Box: show assignedVehicles array  */}
          {/* ════════════════════════════════════════════ */}
          {assignedVehicles.length > 0 && (
            <div className="results-box">
              <h2>Assignment Results</h2>
              {assignedVehicles.map((veh, vi) => (
                <div className="vehicle-result" key={vi}>
                  <h3>
                    Vehicle: {veh.truckId} &nbsp;—
                    &nbsp;Type: {veh.type} &nbsp;·&nbsp;Capacity: {veh.capacity}t
                  </h3>
                  <p>
                    <strong>Current Load:</strong> {veh.currentLoad}t
                  </p>
                  <div className="assigned-customers">
                    <strong>Assigned Customers:</strong>
                    <ul>
                      {veh.assignedCustomers.map((ac, ai) => (
                        <li key={ai}>
                          {ac.CustomerID} ({ac.customerName}) – {ac.loadWeight}t
                        </li>
                      ))}
                    </ul>
                  </div>
                  <div className="route-list">
                    <strong>Route:</strong>
                    <ol>
                      {veh.route.map((step, si) => {
                        if (step[0] === "start") {
                          return (
                            <li key={si}>
                              Start at ({step[1].toFixed(4)}, {step[2].toFixed(4)})
                            </li>
                          );
                        } else if (step[0] === "storage") {
                          return (
                            <li key={si}>
                              Pick up at Storage {step[1]} (lat: {step[2].toFixed(4)}, lng: {step[3].toFixed(4)})
                            </li>
                          );
                        } else if (step[0] === "customer") {
                          return (
                            <li key={si}>
                              Deliver to Customer {step[1]} (lat: {step[2].toFixed(4)}, lng: {step[3].toFixed(4)})
                            </li>
                          );
                        } else {
                          return <li key={si}>{JSON.stringify(step)}</li>;
                        }
                      })}
                    </ol>
                  </div>
                  <hr />
                </div>
              ))}
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

export default App;
